s=(r/'docs/flow-journey.js').read_text().replace("document.querySelector('#top')]","document.querySelector('#top'),document.querySelector('#wing')]").replace('72000','108000')
s=s.replace("for(const f of frames)f.addEventListener('load',()=>{for(const n of ['density','trail','field','grid'])send(n,document.querySelector('#'+n).value);send('running',running);});", """for(const f of frames)f.addEventListener('load',()=>{for(const n of ['density','trail','field','grid'])f.contentWindow?.postMessage({type:'w11-journey-control',name:n,value:document.querySelector('#'+n).value},location.origin);f.contentWindow?.postMessage({type:'w11-journey-control',name:'running',value:running},location.origin);send('arrows',document.querySelector('#pressure-arrows').checked);});""")
s=s.replace('\n})();','''
document.querySelector('#pressure-arrows').onchange=e=>send('arrows',e.target.checked);
for(const button of document.querySelectorAll('[data-preset]'))button.onclick=()=>{const field=button.dataset.preset;document.querySelector('#field').value=field;send('field',field);document.querySelector('#pressure-arrows').checked=field==='pressure';send('arrows',field==='pressure');};
document.querySelector('#wing-angle').onchange=e=>{document.querySelector('#angle-out').textContent=e.target.value+'°';send('wing-angle',Number(e.target.value));};
document.querySelector('#wing-angle').oninput=e=>document.querySelector('#angle-out').textContent=e.target.value+'°';
document.querySelector('#wing-inverted').onchange=e=>send('wing-inverted',e.target.checked);
function tradeoff(){const kmh=Number(document.querySelector('#example-speed').value),v=kmh/3.6,S=Number(document.querySelector('#example-area').value);if(!(S>0&&S<=10))return;document.querySelector('#example-speed-out').textContent=kmh+' km/h · '+v.toFixed(2)+' m/s';const q=.5*1.225*v*v;document.querySelector('#tradeoff').innerHTML=[['Higher-load example',3.8,.85],['Lower-drag example',2,.55]].map(([name,cl,cd])=>'<article><b>'+name+'</b><span>Assumed C↓ '+cl+' · Cᴅ '+cd+'</span><strong>'+Math.round(q*S*cl).toLocaleString()+' N</strong><span>illustrative downforce</span><strong>'+Math.round(q*S*cd).toLocaleString()+' N</strong><span>illustrative drag</span></article>').join('');}
for(const id of ['example-speed','example-area'])document.querySelector('#'+id).oninput=tradeoff;tradeoff();
})();''')
(out/'flow-journey.js').write_text(s)
